import os,subprocess,pty,termios,select,time,errno
def execute(argv,interactive,payload):
    if type(interactive) is not bool or type(payload) is not bytes or len(payload)>4096:raise ValueError('explicit mode and bounded bytes required')
    if not interactive:
        result=subprocess.run(argv,input=payload,capture_output=True,timeout=2)
        return dict(code=result.returncode,stdout=result.stdout,stderr=result.stderr)
    master,slave=pty.openpty();child=None
    try:
        attrs=termios.tcgetattr(slave);attrs[3]&=~termios.ECHO;termios.tcsetattr(slave,termios.TCSANOW,attrs)
        child=subprocess.Popen(argv,stdin=slave,stdout=slave,stderr=slave,start_new_session=True)
        os.close(slave);slave=None
        offset=0
        while offset<len(payload):offset+=os.write(master,payload[offset:])
        output=bytearray();deadline=time.monotonic()+2
        while True:
            remaining=deadline-time.monotonic()
            if remaining<=0:raise RuntimeError('interactive deadline exceeded')
            ready,_,_=select.select([master],[],[],min(.1,remaining))
            if not ready:continue
            try:data=os.read(master,4096)
            except OSError as error:
                if error.errno==errno.EIO:break
                raise
            if not data:break
            output.extend(data)
            if len(output)>65536:raise RuntimeError('interactive output limit exceeded')
        code=child.wait(timeout=max(.01,deadline-time.monotonic()))
        return dict(code=code,stdout=bytes(output),stderr=b'')
    finally:
        if child is not None:
            if child.poll() is None:child.kill()
            child.wait()
        os.close(master)
        if slave is not None:os.close(slave)
```

原题知识说明：
交付终端依赖清单，识别程序是否根据isatty改变颜色、进度条、缓冲、分页和交互提示，并确认是否有受支持的非交互模式。优先选择稳定机器接口；必须使用PTY时，明确回显、行规程、窗口尺寸、控制字符、终端断开和会话退出语义，不能把终端输出当无损二进制流。验收分别使用有终端、无终端、慢读取和交互请求超时，要求任务不会等待不可见输入，日志无控制序列污染或凭据回显。对需要人工确认的步骤，应形成显式审批而不是向提示盲发yes。失败停止该交互会话并核对外部动作是否发生，恢复保留人工入口；不因PTY让命令返回0就取消业务结果检查。

